from pathlib import Path
import argparse,json,hashlib
args=argparse.ArgumentParser();args.add_argument('--input',required=True);args.add_argument('--output',required=True);v=args.parse_args();root=Path(__file__).resolve().parent;m=json.loads((root/'manifest.json').read_text());source=Path(v.input).resolve();target=Path(v.output).resolve();assert source!=target and not target.exists(),'Use a new explicit staging output, never overwrite live/before source';raw=source.read_bytes();assert hashlib.sha256(raw).hexdigest()==m['runtime_before_sha256'],'Runtime source drift';before=(root/'before/compiled/dashboard-render-function.js').read_bytes();after=(root/'candidate/compiled/dashboard-render-function.js').read_bytes();assert raw.count(before)==1;patched=raw.replace(before,after);assert hashlib.sha256(patched).hexdigest()==m['runtime_candidate_sha256'];assert patched.replace(after,before)==raw;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(patched);target.chmod(0o600);print(json.dumps({'staged':True,'sha256':m['runtime_candidate_sha256'],'live_operation':False,'exact_inverse_verified':True}))
